mapper.select:


    e.del_flag = '0'

        and e.elevator_code like concat('%', #{elevatorCode}, '%')


        and e.brand like concat('%', #{brand}, '%')


        and e.building_id = #{buildingId}


        and b.community_id = #{communityId}


        and e.unit_no = #{unitNo}


        and e.status = #{status}


        and e.maintain_unit like concat('%', #{maintainUnit}, '%')


order by e.elevator_id

select b.building_id as buildingId, concat(c.community_name, ' ', b.building_no, ' ', b.unit_no) as buildingName, count(e.elevator_id) as elevatorCount from building b left join community c on b.community_id = c.community_id left join elevator e on e.building_id = b.building_id and e.del_flag = '0' where b.del_flag = '0'
and b.community_id = #{communityId}
group by b.building_id, c.community_name, b.building_no, b.unit_no order by b.building_id

select count(1) from elevator
where del_flag = '0' and elevator_code = #{elevatorCode}

    and elevator_id != #{elevatorId}

