elevator_code = #{elevatorCode}, brand = #{brand}, model = #{model}, building_id = #{buildingId}, unit_no = #{unitNo}, maintain_unit = #{maintainUnit}, install_date = #{installDate}, service_years = #{serviceYears}, cert_file_id = #{certFileId}, status = #{status}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
where elevator_id = #{elevatorId}

